<?php
class Reporte_equipajes extends CI_Controller{
 private $session_data=array();
 public function __construct(){parent::__construct();if(!$this->session->userdata('logged_in'))redirect('','refresh');$this->session_data=$this->session->userdata('logged_in');$this->load->model('Reporte_equipajes_model');$this->load->model('Sistema_model');$this->load->model('Parametro_model');if(!$this->Reporte_equipajes_model->usuario_tiene_rol((int)$this->session_data['usuario_id'],220))show_error('No tiene permiso para generar reportes de Transporte.',403,'Acceso denegado');}
 private function filtros(){ $d=trim((string)$this->input->get('desde',true));$h=trim((string)$this->input->get('hasta',true));if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$d))$d=date('Y-m-01');if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$h))$h=date('Y-m-d');if($d>$h){$x=$d;$d=$h;$h=$x;}return array('desde'=>$d,'hasta'=>$h,'viaje_id'=>(int)$this->input->get('viaje_id',true),'estado'=>trim((string)$this->input->get('estado',true))); }
 public function index(){ $f=$this->filtros();$p=$this->Parametro_model->get_parametros();$data['sistema']=$this->Sistema_model->get_sistema();$data['parametro']=isset($p[0])?$p[0]:$p;$data['filtros']=$f;$data['viajes']=$this->Reporte_equipajes_model->viajes($f);$data['filas']=$this->Reporte_equipajes_model->reporte($f);$data['totales']=$this->Reporte_equipajes_model->totales($f);$data['page_title']='Reporte de equipajes';$data['_view']='reporte_transporte/equipajes';$this->load->view('layouts/main',$data);}
 public function csv(){ $f=$this->filtros();$rs=$this->Reporte_equipajes_model->reporte($f);header('Content-Type: text/csv; charset=UTF-8');header('Content-Disposition: attachment; filename="equipajes_'.$f['desde'].'_'.$f['hasta'].'.csv"');echo "\xEF\xBB\xBF";$x=fopen('php://output','w');fputcsv($x,array('Viaje','Fecha viaje','Pasajero','Documento','Asiento','Cantidad','Peso kg','Exceso kg','Importe','Recibido','Entregado','Etiqueta','Estado'),';');foreach($rs as $r)fputcsv($x,array($r['viaje'],$r['fecha_viaje'],$r['pasajero'],$r['documento'],$r['asiento'],$r['cantidad'],$r['peso'],$r['exceso'],$r['importe'],$r['recibido'],$r['entregado'],$r['etiqueta'],$r['estado']),';');fclose($x);exit;}
}
